import { existsSync, mkdirSync, readFileSync, writeFileSync, openSync, closeSync } from 'node:fs';
import { join } from 'node:path';

export class SettingsManager {
  static create(configDir, agentDir) { return new SettingsManager(configDir, agentDir); }
  constructor(configDir, agentDir) {
    this.agentDir = agentDir;
    this.file = join(agentDir, 'settings.json');
    this.errors = [];
    this.provider = 'fixture-provider';
    this.model = 'fixture-model';
    if (existsSync(this.file)) {
      try {
        const saved = JSON.parse(readFileSync(this.file, 'utf8'));
        this.provider = saved.defaultProvider ?? this.provider;
        this.model = saved.defaultModel ?? this.model;
      } catch (error) {
        if (error?.code !== 'EISDIR') this.errors.push({ error, path: this.file });
      }
    }
  }
  drainErrors() { const errors = this.errors; this.errors = []; return errors; }
  getDefaultProvider() { return this.provider; }
  getDefaultModel() { return this.model; }
  setDefaultModelAndProvider(provider, model) { this.provider = provider; this.model = model; }
  async flush() {
    try {
      mkdirSync(this.agentDir, { recursive: true });
      const fd = openSync(this.file, 'w');
      writeFileSync(fd, JSON.stringify({ defaultProvider: this.provider, defaultModel: this.model }));
      closeSync(fd);
    } catch (error) { this.errors.push({ error, path: this.file }); }
  }
}
